/*
 * A043815  Numbers n such that number of runs in the base 3 representation of
 *          n is congruent to 0 mod 10.
 * https://oeis.org/A043815
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the nth positive integer whose base‑3 representation *
 *            contains a number of runs that is 0 modulo 10. The sequence is *
 *            generated by simple trial‑and‑error
 * Range:     u8 none, u16 n <= 30, u32 n <= 30, u64 n <= 30, u128 n <= 30,
 *            big any n
 * Validated: partial, pass, 30 terms through n = 30 (2026-11-01)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>

/* Returns true when the number of runs in the base‑3 representation of x
 * is congruent to 0 modulo 10. */
static bool runs_congruent_zero(seq_t x)
{
    int runs = 0;
    int prev = -1;          /* -1 is not a valid base‑3 digit */
    while (x > (seq_t)0) {
        int d = (int)(x % (seq_t)3);
        if (d != prev) {
            ++runs;
            prev = d;
        }
        x /= (seq_t)3;
    }
    return (runs % 10) == 0;
}

/* External function required by the build. */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* undefined for offset 1, return 0 */
    idx_t found = 0;               /* count of qualifying numbers found */
    seq_t cand  = 1;               /* current candidate to test */

    for (;; ++cand) {
        if (runs_congruent_zero(cand)) {
            ++found;
            if (found == n) return cand;
        }
    }
}
